  'quality-p1' => 'मर्ज किए गए दस्तावेज़ एकल समेकित दस्तावेज़ के रूप में दिखाई देने चाहिए। पुन: प्रारंभ करने के बजाय मर्ज किए गए दस्तावेज़ों में पृष्ठ क्रमांकन जारी रहना चाहिए। शीर्षलेख और पादलेख सुसंगत होने चाहिए.',
  'quality-p2' => 'विभाजित करते समय, सुनिश्चित करें कि निकाले गए पृष्ठ गुणवत्ता बनाए रखें। विभाजित दस्तावेज़ों के फ़ाइल आकार को कम करने के लिए यदि आवश्यक हो तो संपीड़ित करें।',
  'quality-p3' => 'मर्ज किए गए और विभाजित दस्तावेज़ों का परीक्षण करें। विभिन्न सॉफ़्टवेयर में फ़ॉर्मेटिंग सही है यह सत्यापित करने के लिए एकाधिक रीडर में खोलें।',
  'filesize-heading' => 'फ़ाइल आकार संबंधी विचार',
  'filesize-p1' => 'कई बड़े दस्तावेज़ों को मर्ज करने से बहुत बड़ी फ़ाइलें बनती हैं। कुछ ईमेल प्रणालियाँ अत्यधिक बड़े अनुलग्नकों को संभाल नहीं सकती हैं।',
  'filesize-p2' => 'यदि मर्ज की गई फ़ाइलें आकार सीमा से अधिक हो जाती हैं, तो छोटे मर्ज किए गए समूहों में विभाजित करने पर विचार करें। पचास दस्तावेज़ों को मर्ज करने के बजाय, बीस दस्तावेज़ों को दो बार मर्ज करें।',
  'filesize-p3' => '__COMPRESS_LINK__ ने फ़ाइल का आकार कम करने के लिए दस्तावेज़ों को मर्ज किया। संपीड़न गुणवत्ता हानि के बिना आकार को चालीस से साठ प्रतिशत तक कम कर देता है।',
  'organization-heading' => 'संगठन एवं नामकरण',
  'organization-p1' => 'विलय के बाद, वर्णनात्मक रूप से फ़ाइलों का नाम बदलें। "Merged_Report_2026.pdf" "merged.pdf" से अधिक स्पष्ट है।',
  'organization-p2' => 'विभाजन के बाद निकाले गए पृष्ठों को तार्किक रूप से व्यवस्थित करें। यदि अध्याय द्वारा विभाजित किया जाए, तो अध्याय संख्या और शीर्षक सहित फ़ाइलों को नाम दें।',
  'organization-p3' => 'संस्करण नियंत्रण बनाए रखें. यदि दस्तावेज़ बदलते हैं, तो मर्ज किए गए संस्करणों को अद्यतन किया जाना चाहिए।',
  'organization-p4' => 'मर्ज किए गए दस्तावेज़ों में मेटाडेटा शामिल करें। दस्तावेज़ मर्ज तिथि, स्रोत दस्तावेज़ और उद्देश्य।',
  'automation-heading' => 'स्वचालन उदाहरण',
  'automation-p1' => 'उदाहरण 1: साप्ताहिक रिपोर्ट असेंबली। प्रत्येक शुक्रवार को, विभाग की रिपोर्ट को संगठनात्मक रिपोर्ट में मर्ज करें। स्वचालित वर्कफ़्लो मर्ज को ट्रिगर करता है। मैन्युअल कार्य के बिना स्वचालित रूप से बनाई गई रिपोर्ट।',
  'automation-p2' => 'उदाहरण 2: अनुबंध संयोजन। अनुबंध घटकों को अलग-अलग दस्तावेज़ों में संग्रहीत किया जाता है। जब अनुबंध को अंतिम रूप दिया जाता है, तो घटक दस्तावेज़ स्वचालित रूप से पूर्ण अनुबंध में विलीन हो जाते हैं।',
  'automation-p3' => 'उदाहरण 3: दस्तावेज़ वितरण. लंबे दस्तावेज़ स्वचालित रूप से अध्यायों में विभाजित हो जाते हैं। अभिदाताओं को प्राथमिकताओं के आधार पर केवल उनके लिए प्रासंगिक अध्याय ही प्राप्त होते हैं।',
  'automation-p4' => 'उदाहरण 4: बैकअप संगठन. ईमेल अनुलग्नक स्वचालित रूप से व्यवस्थित फ़ाइलों में विलीन हो जाते हैं। एक ही प्रेषक के अनुलग्नक एक फ़ाइल में संयोजित हो जाते हैं।',
  'mistakes-heading' => 'सामान्य गलतियां',
  'mistakes-p1' => 'अस्पष्ट नामों वाली फ़ाइलें बनाने से मर्ज किए गए दस्तावेज़ों का पता लगाने में समय बर्बाद होता है। हमेशा वर्णनात्मक नामों का प्रयोग करें.',
  'mistakes-p2' => 'दस्तावेज़ों को गलत क्रम में मर्ज करने से अनुपयोगी परिणाम उत्पन्न होते हैं। मर्ज को अंतिम रूप देने से पहले हमेशा ऑर्डर सत्यापित करें।',
  'mistakes-p3' => 'मूल दस्तावेज़ों को बनाए न रखने का मतलब लचीलापन खोना है। यदि मर्ज किए गए संस्करणों को अद्यतन करने की आवश्यकता हो तो मूल दस्तावेज़ रखें।',
  'mistakes-p4' => 'डाउनस्ट्रीम प्रक्रियाओं पर विचार किए बिना विभाजन समस्याएँ पैदा करता है। सत्यापित करें कि डाउनस्ट्रीम उपकरण विभाजित दस्तावेज़ों को संभाल सकते हैं।',
  'mistakes-p5' => 'जटिल दस्तावेज़ वर्कफ़्लो प्रबंधित करने वाली टीमों के लिए, एकीकृत संचालन सबसे अच्छा काम करता है। दस्तावेज़ों को मर्ज करने के बाद, उन्हें वितरण के लिए प्रारूप रूपांतरण या संपीड़न की आवश्यकता हो सकती है। इन परिचालनों की एक साथ योजना बनाने से दक्षता में सुधार होता है।',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-p1' => 'पीडीएफ विलय और विभाजन नियमित दस्तावेज़ प्रबंधन कार्य हैं। उचित उपकरण और वर्कफ़्लो इन प्रक्रियाओं को सुव्यवस्थित करते हैं।',
  'conclusion-p2' => 'कभी-कभी विलय और विभाजन के लिए, ऑनलाइन उपकरण त्वरित समाधान प्रदान करते हैं। नियमित संचालन के लिए, डेस्कटॉप सॉफ़्टवेयर और स्वचालन महत्वपूर्ण समय बचाते हैं।',
  'conclusion-p3' => 'गुणवत्ता सुनिश्चित करने के लिए मर्ज किए गए और विभाजित दस्तावेज़ों का परीक्षण करें। स्पष्ट नामकरण परंपराएँ और संगठन बनाए रखें।',
  'conclusion-p4' => 'अन्य पीडीएफ परिचालनों के साथ विलय और विभाजन को संयोजित करें। __COMPRESS_LINK__ ने आकार कम करने के लिए दस्तावेज़ों को मर्ज किया। __WORD_LINK__ यदि आवश्यक हो तो दस्तावेज़ों को संपादन योग्य प्रारूप में मर्ज करें।',
  'conclusion-p5' => 'कई दस्तावेज़ों का प्रबंधन करने वाले संगठन स्वचालन वर्कफ़्लो से लाभान्वित होते हैं। स्वचालित विलय और विभाजन से मैन्युअल कार्य समाप्त हो जाता है और स्थिरता में सुधार होता है।',
);
